"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["8635"],{2060(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>c,frontMatter:()=>i,contentTitle:()=>a,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"m7-tool-interface-engineering/deep-dive","title":"Deep Dive: The Observer Threat Model and Runtime Isolation","description":"The core lab built a read-only observer and proved, by hand and through the grader, that a write attempt fails because no write tool exists. That is the right result, but \\"the write failed\\" is a symptom \u2014 this page is about the mechanism, because understanding exactly where and why the write fails is what lets you reason about the observer\'s real threat model, and where its guarantee stops. Two questions the lab left open: at what layer, precisely, does a write attempt die \u2014 and what threat does a read-only tool surface not cover? The answer to the second is the reason ToolHive and runtime isolation exist, and it is the supply-chain thread the whole module has been pointing at.","source":"@site/docs/m7-tool-interface-engineering/deep-dive.md","sourceDirName":"m7-tool-interface-engineering","slug":"/m7-tool-interface-engineering/deep-dive","permalink":"/306-agentic-devops-claude/docs/m7-tool-interface-engineering/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive: The Observer Threat Model and Runtime Isolation","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: Tool Interface Engineering: CLI First, MCP When It Earns the Boundary","permalink":"/306-agentic-devops-claude/docs/m7-tool-interface-engineering/quiz"},"next":{"title":"Hooks, Policy, GitOps & the Environment Contract","permalink":"/306-agentic-devops-claude/docs/m8-hooks-policy-gitops/lesson"}}'),s=n(4848),r=n(8453);let i={sidebar_position:4,title:"Deep Dive: The Observer Threat Model and Runtime Isolation",sidebar_label:"Deep Dive (Part 2)"},a="Deep Dive \u2014 The Observer Threat Model and Runtime Isolation",l={},h=[{value:"Where the write actually dies: the protocol, not the permission layer",id:"where-the-write-actually-dies-the-protocol-not-the-permission-layer",level:2},{value:"What &quot;read-only tool surface&quot; does not protect against",id:"what-read-only-tool-surface-does-not-protect-against",level:2},{value:"ToolHive: containing the server process itself",id:"toolhive-containing-the-server-process-itself",level:2},{value:"Where you&#39;ll use this",id:"where-youll-use-this",level:2}];function d(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,r.R)(),...e.components},{Details:n}=t;return n||function(e,t){throw Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"deep-dive--the-observer-threat-model-and-runtime-isolation",children:"Deep Dive \u2014 The Observer Threat Model and Runtime Isolation"})}),"\n",(0,s.jsxs)(t.p,{children:['The core lab built a read-only observer and proved, by hand and through the grader, that a write attempt fails because no write tool exists. That is the right result, but "the write failed" is a ',(0,s.jsx)(t.em,{children:"symptom"})," \u2014 this page is about the ",(0,s.jsx)(t.em,{children:"mechanism"}),", because understanding exactly where and why the write fails is what lets you reason about the observer's real threat model, and where its guarantee stops. Two questions the lab left open: at what layer, precisely, does a write attempt die \u2014 and what threat does a read-only tool surface ",(0,s.jsx)(t.em,{children:"not"})," cover? The answer to the second is the reason ToolHive and runtime isolation exist, and it is the supply-chain thread the whole module has been pointing at."]}),"\n",(0,s.jsx)(t.admonition,{title:"This extends the lab \u2014 it does not repeat it",type:"note",children:(0,s.jsxs)(t.p,{children:["You already know ",(0,s.jsx)(t.em,{children:"that"})," the observer refuses to write. This page is about the layer underneath: the MCP protocol's ",(0,s.jsx)(t.code,{children:"tools/list"}),' contract, why "no write tool" is a stronger property than "write is denied," and \u2014 the part most people miss \u2014 that a read-only ',(0,s.jsx)(t.em,{children:"tool surface"})," says nothing about whether the ",(0,s.jsx)(t.em,{children:"server process itself"})," is trustworthy. If you skipped the lab's Step 4, build the observer first; everything here operates on it."]})}),"\n",(0,s.jsx)(t.h2,{id:"where-the-write-actually-dies-the-protocol-not-the-permission-layer",children:"Where the write actually dies: the protocol, not the permission layer"}),"\n",(0,s.jsxs)(t.p,{children:["Trace a write attempt through the stack and you find it fails earlier than most people assume. In Module 2, a blocked command dies at the ",(0,s.jsx)(t.em,{children:"permission layer"}),": the agent forms a valid ",(0,s.jsx)(t.code,{children:"Bash(kubectl delete ...)"})," call, and a deny rule catches it before execution. The capability existed; a check stopped its use. A write attempt against the observer dies somewhere different and earlier."]}),"\n",(0,s.jsxs)(t.p,{children:["When Claude Code connects to an MCP server, the very first thing it does after ",(0,s.jsx)(t.code,{children:"initialize"})," is call ",(0,s.jsx)(t.code,{children:"tools/list"}),". The server responds with the ",(0,s.jsx)(t.em,{children:"complete, exhaustive"})," set of tools it offers \u2014 for the observer, exactly ",(0,s.jsx)(t.code,{children:"get_health"}),", ",(0,s.jsx)(t.code,{children:"get_readiness"}),", ",(0,s.jsx)(t.code,{children:"get_info"}),". That list ",(0,s.jsx)(t.strong,{children:"is"})," the agent's entire universe of callable operations for that server. The agent cannot call a tool that was not in the list, because there is no protocol message that would name it \u2014 ",(0,s.jsx)(t.code,{children:"tools/call"})," takes a tool ",(0,s.jsx)(t.code,{children:"name"}),", and a name the server never advertised resolves to nothing."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," this is the difference between a restaurant that ",(0,s.jsx)(t.em,{children:"refuses"})," to make a dish and a restaurant where the dish is ",(0,s.jsx)(t.em,{children:"not on the menu and the kitchen has no recipe for it"}),". The first still has the capability \u2014 the ingredients are in the back, and whether you get the dish depends on the waiter enforcing a rule. The second has no path to the dish at all: you cannot order what the menu does not list, and even if you described it, the kitchen has nothing to make it from. A deny rule is the refusing waiter. The ",(0,s.jsx)(t.code,{children:"tools/list"}),' contract is the menu with no such item and a kitchen with no such recipe. You are not being told "no" \u2014 you are trying to reference something that does not exist in the interface.']}),"\n",(0,s.jsx)(t.mermaid,{value:"sequenceDiagram\n    participant A as Agent\n    participant CC as Claude Code\n    participant S as northstar-observer\n    A->>CC: initialize\n    CC->>S: initialize\n    S--\x3e>CC: capabilities\n    CC->>S: tools/list\n    S--\x3e>CC: [get_health, get_readiness, get_info]\n    Note over CC: These three names are the<br/>agent's ENTIRE callable surface\n    A->>CC: \"restart orders-api\"\n    Note over A,CC: no tool named 'restart' was ever advertised\n    CC--\x3e>A: nothing to call \u2014 capability absent\n    Note over S: The permission layer was never<br/>reached \u2014 there was no valid call to check"}),"\n",(0,s.jsxs)(t.p,{children:["Read the sequence carefully: the permission layer is ",(0,s.jsx)(t.em,{children:"never consulted"})," for a write, because there is no valid write call to consult it about. In the lab's Step 6 the agent did not attempt a restart and get denied \u2014 it inspected its tool surface, found no restart tool, and reported the absence. This is why the observer's guarantee is stronger than a deny rule: a deny rule is a control you can get ",(0,s.jsx)(t.em,{children:"wrong"})," (too narrow a pattern, an unanticipated command shape \u2014 the Module 2 failure modes), and it sits on top of a capability that is still there. The absence of a tool is not a control that can be misconfigured. There is nothing to configure."]}),"\n",(0,s.jsxs)(t.p,{children:['You can see the two layers behave differently with a direct probe. Ask the server for a tool it never listed and watch it resolve to "unknown" \u2014 a ',(0,s.jsx)(t.em,{children:"nonexistence"})," error, not a ",(0,s.jsx)(t.em,{children:"forbidden"})," error:"]}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-bash",children:'docker compose --profile core up -d\nprintf \'%s\\n\' \\\n  \'{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}\' \\\n  \'{"jsonrpc":"2.0","id":11,"method":"tools/call","params":{"name":"scale","arguments":{"replicas":0}}}\' \\\n  \'{"jsonrpc":"2.0","id":12,"method":"tools/call","params":{"name":"delete","arguments":{"service":"orders-api"}}}\' \\\n  | node platform/mcp-servers/northstar-observer.js | jq -c \'select(.id>=11) | {id, error: .error.message}\'\n'})}),"\n",(0,s.jsxs)(n,{children:[(0,s.jsx)("summary",{children:"Expected output"}),(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{children:'{"id":11,"error":"unknown tool: scale"}\n{"id":12,"error":"unknown tool: delete"}\n'})}),(0,s.jsxs)(t.p,{children:["Both write-shaped calls \u2014 ",(0,s.jsx)(t.code,{children:"scale"}),", ",(0,s.jsx)(t.code,{children:"delete"})," \u2014 come back as ",(0,s.jsx)(t.code,{children:"unknown tool"}),', not "permission denied." The distinction is the whole point. A permission-denied response means the tool exists and a policy rejected the call; you would harden that by tightening the policy. An ',(0,s.jsx)(t.code,{children:"unknown tool"})," response means there is nothing there \u2014 no policy is involved, and no policy ",(0,s.jsx)(t.em,{children:"needs"})," to be, because the capability was never part of the surface. Naming the tool in ",(0,s.jsx)(t.code,{children:"--allowedTools"})," on the client side would not help either: allowing a tool the server does not expose still leaves nothing to call."]})]}),"\n",(0,s.jsx)(t.h2,{id:"what-read-only-tool-surface-does-not-protect-against",children:'What "read-only tool surface" does not protect against'}),"\n",(0,s.jsxs)(t.p,{children:["Here is the threat the observer pattern does ",(0,s.jsx)(t.em,{children:"not"})," cover, and it is the one that matters most for production. The read-only guarantee is about ",(0,s.jsx)(t.em,{children:"what the agent can ask the server to do"}),". It says nothing about ",(0,s.jsx)(t.em,{children:"what the server process itself does"})," when it runs. And an MCP server is a program \u2014 the observer is ",(0,s.jsx)(t.code,{children:"node platform/mcp-servers/northstar-observer.js"}),", a process Claude Code launches on your machine, with your user's privileges, your filesystem, your network."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"}),' the tool surface is the set of buttons on a vending machine\'s front panel \u2014 you have designed it so the only buttons are "dispense water" and "dispense juice," and a customer cannot dispense anything else. But the machine\'s ',(0,s.jsx)(t.em,{children:"internal wiring"})," is a separate concern entirely. If the machine's manufacturer wired it to also quietly phone home with everyone's purchase history, or to overheat, the limited front panel does nothing about that \u2014 the customer's restricted buttons never touched the machine's own behavior. A read-only tool surface constrains the customer (the agent). It does not vouch for the machine (the server code). For a server you wrote and can read \u2014 like the observer \u2014 that gap is small, because you know the wiring. For a server you ",(0,s.jsx)(t.code,{children:"npm install"})," from a third party, the gap is the whole risk."]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart TD\n    subgraph COVERED["What a read-only tool surface covers"]\n      C1["Agent asks server to write"] --\x3e C2["No write tool \u2014 blocked structurally"]\n    end\n    subgraph UNCOVERED["What it does NOT cover"]\n      U1["Server process reads your ~/.aws/credentials"]\n      U2["Server process opens an outbound connection"]\n      U3["Server process writes to your filesystem"]\n      U1 --\x3e UX["The tool surface never sees this \u2014<br/>it is the server\'s own behavior"]\n      U2 --\x3e UX\n      U3 --\x3e UX\n    end\n    style C2 fill:#e8f5e9,stroke:#388e3c\n    style UX fill:#ffebee,stroke:#c62828'}),"\n",(0,s.jsxs)(t.p,{children:["This is why the module kept returning to ",(0,s.jsx)(t.em,{children:"supply chain"}),". Two separate trust questions live in every MCP server, and conflating them is the mistake:"]}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"What can the agent make the server do?"})," \u2014 answered by the tool surface. A read-only observer answers this well: nothing but reads."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"What does the server do on its own, with the privileges you launched it with?"})," \u2014 answered by ",(0,s.jsx)(t.em,{children:"nothing in the tool surface"}),". It is answered only by trusting the code, or by containing the process."]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:['For the observer you built, question 2 is easy: you read the whole file, it makes outbound HTTP to two localhost ports and nothing else. For a third-party MCP server \u2014 a database server, a cloud-provider server, one of dozens on a public registry \u2014 you often cannot read all the code, and "it only exposes read tools" tells you ',(0,s.jsx)(t.em,{children:"nothing"})," about what its process does with the credentials and filesystem access you handed it."]}),"\n",(0,s.jsx)(t.h2,{id:"toolhive-containing-the-server-process-itself",children:"ToolHive: containing the server process itself"}),"\n",(0,s.jsxs)(t.p,{children:["This is the gap ToolHive fills. ToolHive (an open-source project from Stacklok) runs each MCP server inside its own locked-down container instead of as a bare process on your host, so the ",(0,s.jsx)(t.em,{children:"server's own behavior"})," is constrained regardless of what tools it exposes. It answers question 2 the way the observer pattern answers question 1 \u2014 structurally, by removing capability rather than policing it."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Analogy:"})," if a read-only tool surface is choosing which buttons the vending machine has, ToolHive is putting the whole machine inside a locked room with a single, metered pipe for exactly the one utility it legitimately needs. Even if the machine's internal wiring is malicious, it can only reach what the room's one pipe allows \u2014 it cannot touch the rest of the building. You have stopped trusting the machine's insides and started containing them."]}),"\n",(0,s.jsx)(t.p,{children:"Concretely, running an MCP server under ToolHive gives you:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Filesystem isolation"})," \u2014 the server sees only the paths you mount into its container, not your whole home directory. A server that tried to read ",(0,s.jsx)(t.code,{children:"~/.aws/credentials"})," finds no such file, because it was never mounted."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Network isolation"})," \u2014 the server reaches only the endpoints you allow. An observer that should talk to two localhost ports is given exactly those; an unexpected outbound connection has nowhere to go."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Least-privilege secrets"})," \u2014 credentials are injected scoped and controlled, rather than the server inheriting your ambient environment."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"A vetted registry"}),' \u2014 a curated set of known MCP servers, so the supply-chain question ("is this server code trustworthy at all?") has a better default answer than "whatever the internet published."']}),"\n"]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n    subgraph HOST["Bare process (host privileges)"]\n      P["node server.js<br/>your fs \xb7 your network \xb7 your env"]\n    end\n    subgraph TH["Under ToolHive (contained)"]\n      C["server in a container<br/>only mounted paths<br/>only allowed endpoints<br/>scoped secrets"]\n    end\n    style P fill:#ffebee,stroke:#c62828\n    style C fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,s.jsxs)(t.p,{children:["The two controls compose, and that is the point. ",(0,s.jsx)(t.strong,{children:"A read-only tool surface constrains what the agent can ask; ToolHive constrains what the server can do."})," Together they close both trust questions: the agent cannot request a write (no write tool), and the server cannot exfiltrate or tamper on its own (no filesystem or network reach beyond what you granted). For the observer you built \u2014 code you wrote and can audit \u2014 the tool surface alone is a reasonable posture. The moment you reach for a server you did ",(0,s.jsx)(t.em,{children:"not"})," write, runtime isolation stops being optional hardening and becomes the control that makes running someone else's code sane."]}),"\n",(0,s.jsx)(t.admonition,{title:"The trap: \"it's read-only, so it's safe to install\"",type:"warning",children:(0,s.jsxs)(t.p,{children:["The most common supply-chain mistake with MCP is reading a third-party server's tool list, seeing only ",(0,s.jsx)(t.code,{children:"get_*"})," tools, and concluding the server is safe. That reasoning answers question 1 and ignores question 2 entirely. A server can expose ",(0,s.jsx)(t.em,{children:"only read tools to the agent"}),' while its own process reads your credentials, opens outbound connections, and writes files \u2014 none of which the tool surface constrains, because they are the server\'s behavior, not the agent\'s requests. "Read-only tools" is not "safe process." Judge the server\'s code, or contain it (ToolHive), or both \u2014 never infer process safety from the tool surface.']})}),"\n",(0,s.jsx)(t.h2,{id:"where-youll-use-this",children:"Where you'll use this"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Vetting an MCP server before adding it to a project"})," (the IaC/FinOps and Kubernetes modules bring real third-party servers into play). Ask the two questions separately: what can the agent make it do (its tool surface), and what can the process do on its own (its code and privileges). A read-only tool list answers only the first. If you cannot fully audit the code, run it under ToolHive so the second question is answered by containment, not trust."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Designing your own observer for production"})," (the observability and capstone modules). Writing a read-only tool surface is the right first move, but pair it with a least-privilege ",(0,s.jsx)(t.em,{children:"credential"})," for the server itself \u2014 the read-only KUBECONFIG from the lesson \u2014 so that even the server's own process cannot write, not just the agent through it. Two layers, each removing capability."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Explaining to a security reviewer why an agent with an observer is safe on production."})," The strong, defensible claim is structural: the agent has no write tool to call (protocol-level, not a deny rule that could be misconfigured), ",(0,s.jsx)(t.em,{children:"and"}),' the server runs contained with a read-scoped credential and no filesystem or network reach beyond the cluster read API. That pair \u2014 surface plus isolation \u2014 is a posture a reviewer can accept, in a way that "we told it not to write" never is.']}),"\n"]})]})}function c(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>a});var o=n(6540);let s={},r=o.createContext(s);function i(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);